parts.text:
{
  "extractions": [
    {
      "authority": "Each House shall be the Judge of the Elections, Returns and Qualifications of its own Members",
      "authority_attributes": {
        "summary": "Each House has the authority to judge the elections, returns, and qualifications of its own members",
        "actor": "Each House",
        "relation": "none",
        "applies_to": []
      }
    },
    {
      "threshold": "a Majority of each shall constitute a Quorum to do Business",
      "threshold_attributes": {
        "summary": "A majority constitutes a quorum to do business",
        "actor": "Majority of each House",
        "relation": "none",
        "applies_to": []
      }
    },
    {
      "permission": "a smaller Number may adjourn from day to day",
      "permission_attributes": {
        "summary": "A smaller number than a quorum may adjourn daily",
        "actor": "smaller Number",
        "relation": "none",
        "applies_to": []
      }
    },
    {
      "permission": "may be authorized to compel the Attendance of absent Members",
      "permission_attributes": {
        "summary": "A smaller number may be authorized to compel absent members to attend",
        "actor": "smaller Number",
        "relation": "none",
        "applies_to": []
      }
    },
    {
      "condition": "in such Manner, and under such Penalties as each House may provide",
      "condition_attributes": {
        "summary": "Compulsion of attendance is subject to the manner and penalties provided by each House",
        "actor": "Each House",
        "relation": "scope",
        "applies_to": [
          "may be authorized to compel the Attendance of absent Members"
        ]
      }
    },
    {
      "permission": "Each House may determine the Rules of its Proceedings",
      "permission_attributes": {
        "summary": "Each House may determine the rules governing its proceedings",
        "actor": "Each House",
        "relation": "none",
        "applies_to": []
      }
    },
    {
      "permission": "punish its Members for disorderly Behaviour",
      "permission_attributes": {
        "summary": "Each House may punish its members for disorderly behavior",
        "actor": "Each House",
        "relation": "none",
        "applies_to": []
      }
    },
    {
      "condition": "with the Concurrence of two thirds",
      "condition_attributes": {
        "summary": "Expelling a member requires the concurrence of two-thirds",
        "actor": "Each House",
        "relation": "prerequisite",
        "applies_to": [
          "expel a Member"
        ]
      }
    },
    {
      "permission": "expel a Member",
      "permission_attributes": {
        "summary": "Each House may expel a member with two-thirds concurrence",
        "actor": "Each House",
        "relation": "none",
        "applies_to": []
      }
    },
    {
      "requirement": "Each House shall keep a Journal of its Proceedings",
      "requirement_attributes": {
        "summary": "Each House must maintain a journal of its proceedings",
        "actor": "Each House",
        "relation": "none",
        "applies_to": []
      }
    },
    {
      "requirement": "from time to time publish the same",
      "requirement_attributes": {
        "summary": "Each House must periodically publish its journal, subject to secrecy exceptions",
        "actor": "Each House",
        "relation": "none",
        "applies_to": []
      }
    },
    {
      "exception": "excepting such Parts as may in their Judgment require Secrecy",
      "exception_attributes": {
        "summary": "Parts judged to require secrecy are exempt from publication",
        "actor": "Each House",
        "relation": "exception",
        "applies_to": [
          "from time to time publish the same"
        ]
      }
    },
    {
      "condition": "at the Desire of one fifth of those Present",
      "condition_attributes": {
        "summary": "The request of one-fifth of members present triggers entry of yeas and nays into the journal",
        "actor": "one fifth of those Present",
        "relation": "trigger",
        "applies_to": [
          "the Yeas and Nays of the Members of either House on any question shall, at the Desire of one fifth of those Present, be entered on the Journal"
        ]
      }
    },
    {
      "requirement": "the Yeas and Nays of the Members of either House on any question shall, at the Desire of one fifth of those Present, be entered on the Journal",
      "requirement_attributes": {
        "summary": "Yeas and nays must be recorded in the journal when desired by one-fifth of those present",
        "actor": "either House",
        "relation": "none",
        "applies_to": []
      }
    },
    {
      "condition": "during the Session of Congress",
      "condition_attributes": {
        "summary": "Adjournment restrictions apply during the session of Congress",
        "actor": "Neither House",
        "relation": "scope",
        "applies_to": [
          "Neither House, during the Session of Congress, shall, without the Consent of the other, adjourn for more than three days",
          "nor to any other Place than that in which the two Houses shall be sitting"
        ]
      }
    },
    {
      "condition": "without the Consent of the other",
      "condition_attributes": {
        "summary": "Restrictions apply in the absence of consent from the other House",
        "actor": "Neither House",
        "relation": "scope",
        "applies_to": [
          "Neither House, during the Session of Congress, shall, without the Consent of the other, adjourn for more than three days",
          "nor to any other Place than that in which the two Houses shall be sitting"
        ]
      }
    },
    {
      "prohibition": "Neither House, during the Session of Congress, shall, without the Consent of the other, adjourn for more than three days",
      "prohibition_attributes": {
        "summary": "Neither House may adjourn for more than three days without consent during session",
        "actor": "Neither House",
        "relation": "none",
        "applies_to": []
      }
    },
    {
      "prohibition": "nor to any other Place than that in which the two Houses shall be sitting",
      "prohibition_attributes": {
        "summary": "Neither House may adjourn to another place without consent during session",
        "actor": "Neither House",
        "relation": "none",
        "applies_to": []
      }
    }
  ]
}
